px solid #40495a;border-bottom-width:2px;background:#222937;padding:3px 6px;border-radius:4px;color:#cbd2d7}.panel{background:linear-gradient(145deg,#1d2330,#171c27);border:1px solid #333c4c;box-shadow:0 16px 42px #080a0f55;display:flex;flex-direction:column;min-height:0}.hero{padding:17px 17px 14px;border-bottom:1px solid var(--line)}.herotop{display:flex;justify-content:space-between;align-items:center}.hero h2{margin:0;font-size:17px}.badge{color:var(--gold);font:10px 'DM Mono',monospace;border:1px solid #63563e;padding:4px 7px;border-radius:3px}.bars{margin-top:14px}.barlabel{display:flex;justify-content:space-between;color:var(--muted);font:10px 'DM Mono',monospace;margin:7px 0 5px}.bar{height:7px;background:#10141d;border:1px solid #333b49;border-radius:8px;overflow:hidden}.bar>i{height:100%;display:block;transition:width .2s;background:linear-gradient(90deg,#d95f63,#f59476)}#xpbar>i{background:linear-gradient(90deg,#6686d8,#92b7ff)}.statrow{display:flex;gap:12px;margin-top:12px;color:#aab3c1;font:10px 'DM Mono',monospace}.statrow b{color:#eef0e7;font-weight:500}.section{padding:13px 15px;border-bottom:1px solid var(--line)}.sectionhead{display:flex;justify-content:space-between;align-items:center;font:10px 'DM Mono',monospace;letter-spacing:.13em;color:#a9b2c1;margin-bottom:10px}.sectionhead button{font:10px 'DM Mono',monospace;background:none;border:0;color:var(--gold);cursor:pointer}.geargrid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.gear{background:#151a24;border:1px solid #30394a;border-radius:4px;padding:8px 9px;min-width:0}.gearlabel{font:9px 'DM Mono',monospace;color:#788497;letter-spacing:.08em}.gearname{font-size:11px;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#e5e8e2}.gearname.empty{color:#667080;font-style:italic}.inventory{padding:13px 15px 7px;flex:1;min-height:100px;overflow:auto}.items{display:flex;flex-direction:column;gap:5px}.item{display:flex;align-items:center;gap:9px;background:#1a202c;border:1px solid #30394a;border-radius:4px;padding:7px 8px;cursor:pointer;transition:background .12s,border .12s}.item:hover,.item.selected{background:#242d3b;border-color:#69748a}.icon{width:27px;height:27px;display:grid;place-items:center;background:#252d3b;border-radius:4px;font-size:15px;flex:none}.itemtext{min-width:0;flex:1}.itemname{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.itemdesc{font:9px 'DM Mono',monospace;color:#8590a1;margin-top:2px}.rarity{color:var(--gold)}.itemcount{font:10px 'DM Mono',monospace;color:#95a1b2}.itemactions{display:flex;gap:5px}.action{font:9px 'DM Mono',monospace;background:#2c3545;border:1px solid #465267;border-radius:3px;padding:5px 7px;cursor:pointer}.action:hover{border-color:var(--gold);color:var(--gold)}.log{height:114px;padding:11px 15px;border-top:1px solid var(--line);overflow:auto;font:10px/1.55 'DM Mono',monospace;color:#8994a5}.log p{margin:0 0 3px}.log p:first-child{color:#d8dccf}.log .good{color:var(--mint)}.log .warn{color:var(--red)}.log .loot{color:var(--gold)}.mobilepad{display:none}.overlay{position:absolute;inset:8px;background:#0b0f17dd;z-index:5;display:none;align-items:center;justify-content:center;text-align:center;padding:24px}.overlay.show{display:flex}.modal{max-width:380px}.modal .crest{font-size:45px;color:var(--gold)}.modal h2{font-size:28px;letter-spacing:.08em;margin:8px 0}.modal p{color:#aab3c1;line-height:1.55}.primary{background:#c99450;color:#171923;border:0;border-radius:4px;padding:11px 20px;font-weight:700;cursor:pointer}.primary:hover{background:#edc477}.toast{position:absolute;bottom:40px;left:50%;transform:translateX(-50%);background:#111720e8;border:1px solid #626b78;padding:8px 12px;border-radius:4px;font:11px 'DM Mono',monospace;color:var(--gold);opacity:0;pointer-events:none;transition:opacity .2s;white-space:nowrap}.toast.show{opacity:1}
