</style></head>
<body><main class="shell"><section class="gamecol"><header class="topbar"><div class="brand"><div class="sigil"><span>✦</span></div><div><h1>DEEPVAULT</h1><small>THE SHATTERED BELOW</small></div></div><div class="runinfo">RUN <strong id="runnum">01</strong><br><span id="seed">DEPTH 01</span></div></header><div class="frame"><div class="canvaswrap"><canvas id="game" width="800" height="608" aria-label="Dungeon game view"></canvas><div class="floortag">DEPTH <b id="depthtag">01</b> <span>·</span> <span id="roomtag">THE HOLLOW COURT</span></div><div class="overlay" id="overlay"><div class="modal"><div class="crest" id="crest">✦</div><h2 id="endtitle">THE VAULT CLAIMS ANOTHER</h2><p id="endcopy"></p><button class="primary" id="restart">DESCEND AGAIN</button></div></div><div class="toast" id="toast"></div></div><div class="controls"><div class="keys"><span class="key">W</span><span class="key">A</span><span class="key">S</span><span class="key">D</span><span>MOVE</span><span style="margin-left:7px" class="key">SPACE</span><span>WAIT</span></div><span class="hint">CLICK AN ADJACENT TILE TO MOVE</span><div class="mobilepad"><button data-dir="up">▲</button><button data-dir="wait">·</button><button data-dir="right">▶</button><button data-dir="left">◀</button><button data-dir="down">▼</button></div></div></div></section>
<aside class="panel"><div class="hero"><div class="herotop"><h2>Wayfarer</h2><span class="badge" id="levelbadge">LVL 1</span></div><div class="bars"><div class="barlabel"><span>VITALITY</span><span id="hptext">30 / 30</span></div><div class="bar"><i id="hpbar" style="width:100%"></i></div><div class="barlabel"><span>EXPERIENCE</span><span id="xptext">0 / 20</span></div><div class="bar" id="xpbar"><i style="width:0%"></i></div></div><div class="statrow"><span>⚔ <b id="attackstat">4</b> ATK</span><span>⬟ <b id="defensestat">1</b> ARM</span><span>◈ <b id="goldstat">0</b> GOLD</span></div></div>
<div class="section"><div class="sectionhead"><span>WORN GEAR</span><span>4 SLOTS</span></div><div class="geargrid"><div class="gear"><div class="gearlabel">WEAPON</div><div class="gearname" id="gearweapon">Rusty Dagger</div></div><div class="gear"><div class="gearlabel">ARMOR</div><div class="gearname" id="geararmor">Traveler’s Coat</div></div><div class="gear"><div class="gearlabel">RING</div><div class="gearname empty" id="gearring">Empty</div></div><div class="gear"><div class="gearlabel">CHARM</div><div class="gearname empty" id="gearcharm">Empty</div></div></div></div>
<div class="inventory"><div class="sectionhead"><span>PACK</span><span id="packcount">2 ITEMS</span></div><div class="items" id="items"><div class="item " data-i="0"><div class="icon">⚗</div><div class="itemtext"><div class="itemname ">Healing Draught ×2</div><div class="itemdesc">Restore 14 vitality</div></div><div class="itemactions"><button class="action" data-act="use">USE</button></div></div><div class="item " data-i="1"><div class="icon">ϟ</div><div class="itemtext"><div class="itemname ">Scroll of Sparks</div><div class="itemdesc">Strike every nearby foe</div></div><div class="itemactions"><button class="action" data-act="use">USE</button></div></div></div></div><div class="log" id="log" aria-live="polite"><p class="">Cold air spills from the stairwell. Find the way down.</p></div></aside></main>
<script>
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=25,H=19,T=32;let map,seen,rooms,player,enemies,loot,depth=1,run=1,turn=0,logs=[],gameOver=false,selected=null;
const gearTypes=['weapon','armor','ring','charm'];
const gearDefs=[
 {name:'Rusty Dagger',type:'weapon',icon:'†',atk:2,desc:'+2 attack'}, {name:'Ashen Shortsword',type:'weapon',icon:'⚔',atk:4,desc:'+4 attack'}, {name:'Moonsteel Sabre',type:'weapon',icon:'⚔',atk:7,desc:'+7 attack · swift'}, {name:'Runebreaker',type:'weapon',icon:'⚔',atk:10,desc:'+10 attack · rare',rarity:1},
 {name:'Traveler’s Coat',type:'armor',icon:'◈',arm:1,desc:'+1 armor'}, {name:'Scale Vest',type:'armor',icon:'▣',arm:3,desc:'+3 armor'}, {name:'Warden Plate',type:'armor',icon:'▣',arm:5,desc:'+5 armor · rare',rarity:1},
 {name:'Copper Ring',type:'ring',icon:'○',atk:1,desc:'+1 attack'}, {name:'Ring of Mending',type:'ring',icon:'◉',regen:1,desc:'Restore 1 HP each floor'}, {name:'Gilded Band',type:'ring',icon:'◎',arm:2,desc:'+2 armor'},
 {name:'Ember Charm',type:'charm',icon:'✧',atk:2,desc:'+2 attack'}, {name:'Foxbone Talisman',type:'charm',icon:'⌘',arm:1,desc:'+1 armor · +1 attack'}
];
const enemyDefs=[{name:'Gloom Rat',icon:'r',hp:7,atk:3,xp:5,color:'#bc8a77'},{name:'Vault Skeleton',icon:'s',hp:12,atk:4,xp:8,color:'#d8d1b3'},{name:'Mire Wisp',icon:'w',hp:10,atk:5,xp:9,color:'#8ec9cb'},{name:'Ironbound Brute',icon:'B',hp:21,atk:7,xp:15,color:'#d48770'}];
const itemDefs=[{name:'Healing Draught',icon:'⚗',kind:'potion',desc:'Restore 14 vitality'},{name:'Greater Draught',icon:'⚗',kind:'potion',desc:'Restore 25 vitality'},{name:'Scroll of Sparks',icon:'ϟ',kind:'scroll',desc:'Strike every nearby foe'},{name:'Scroll of Warding',icon:'▤',kind:'scroll',desc:'Gain 4 temporary armor'}];
const rand=(n)=>Math.floor(Math.random()*n),pick=a=>a[rand(a.length)],clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function log(text,kind=''){logs.unshift({text,kind});logs=logs.slice(0,7);document.getElementById('log').innerHTML=logs.map(x=>`<p class="${x.kind}">${x.text}</p>`).join('')}
function room(x,y,w,h){return{x,y,w,h,cx:Math.floor(x+w/2),cy:Math.floor(y+h/2)}}
function carveRoom(r){for(let y=r.y;y<r.y+r.h;y++)for(let x=r.x;x<r.x+r.w;x++)map[y][x]=0}
function carveH(x1,x2,y){for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)map[y][x]=0}
function carveV(y1,y2,x){for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)map[y][x]=0}
function freeFloor(){let x,y,n=0;do{x=2+rand(W-4);y=2+rand(H-4)}while(map[y][x]!==0&&n++<1000);return{x,y}}
function makeFloor(){
 map=Array.from({length:H},()=>Array(W).fill(1));seen=Array.from({length:H},()=>Array(W).fill(false));rooms=[];
 for(let i=0;i<42&&rooms.length<8;i++){let w=4+rand(5),h=3+rand(4),x=1+rand(W-w-2),y=1+rand(H-h-2),r=room(x,y,w,h);if(rooms.every(q=>r.x>q.x+q.w+1||r.x+r.w+1<q.x||r.y>q.y+q.h+1||r.y+r.h+1<q.y)){carveRoom(r);if(rooms.length){let p=rooms[rooms.length-1];if(rand(2)){carveH(p.cx,r.cx,p.cy);carveV(p.cy,r.cy,r.cx)}else{carveV(p.cy,r.cy,p.cx);carveH(p.cx,r.cx,r.cy)}}rooms.push(r)}}
 if(!rooms.length){let r=room(3,3,18,12);carveRoom(r);rooms=[r]}
 player.x=rooms[0].cx;player.y=rooms[0].cy;loot=[];enemies=[];
 let last=rooms[rooms.length-1];map[last.cy][last.cx]=2;
 for(let i=1;i<rooms.length;i++){let r=rooms[i];for(let j=0;j<(depth>1?2:1);j++){let p={x:r.cx+rand(Math.max(1,r.w-2))-Math.floor((r.w-2)/2),y:r.cy+rand(Math.max(1,r.h-2))-Math.floor((r.h-2)/2)};if(map[p.y]?.[p.x]===0&&!(p.x===player.x&&p.y===player.y))spawnEnemy(p.x,p.y)}}
 for(let i=0;i<4;i++){let p=freeFloor();loot.push({x:p.x,y:p.y,...itemLoot()})}
 for(let i=0;i<Math.max(1,rooms.length-2);i++){let p=freeFloor();loot.push({x:p.x,y:p.y,...gearLoot()})}
 for(let i=0;i<3;i++){let p=freeFloor();loot.push({x:p.x,y:p.y,name:'Gold',kind:'gold',icon:'◈',amount:4+rand(12),desc:'A handful of old coins'})}
 if(depth===1)log('Cold air spills from the stairwell. Find the way down.');else log(`You descend to depth ${depth}. The vault grows restless.`,`warn`);
 document.getElementById('depthtag').textContent=String(depth).padStart(2,'0');document.getElementById('roomtag').textContent=pick(['THE ENTRY VAULT','THE SUNKEN ARCHIVE','THE ASHEN GALLERY','THE HOLLOW COURT','THE DROWNED CHAPEL']);reveal();render();
}
function spawnEnemy(x,y){let pool=depth<3?enemyDefs.slice(0,2):depth<5?enemyDefs.slice(0,3):enemyDefs;let d=pick(pool),scale=1+(depth-1)*.16;enemies.push({x,y,name:d.name,icon:d.icon,hp:Math.ceil(d.hp*scale),maxhp:Math.ceil(d.hp*scale),atk:d.atk+Math.floor((depth-1)/2),xp:d.xp,color:d.color})}
function itemLoot(){let d=pick(itemDefs);return{...d,kind:d.kind}}
function gearLoot(){let pool=gearDefs.filter(g=>g.rarity?depth>=3:true);return{...pick(pool),kind:'gear'}}
function equipped(type){return player.gear[type]}
function stats(){let atk=player.baseAtk,arm=player.baseArm;for(let g of Object.values(player.gear)){if(g){atk+=g.atk||0;arm+=g.arm||0}}return{atk,arm}}
function start(){depth=1;turn=0;gameOver=false;selected=null;logs=[];player={x:0,y:0,hp:30,maxhp:30,xp:0,level:1,gold:0,baseAtk:2,baseArm:0,gear:{weapon:gearDefs[0],armor:gearDefs[4],ring:null,charm:null},bag:[{...itemDefs[0],count:2},{...itemDefs[2],count:1}]};run++;document.getElementById('runnum').textContent=String(run).padStart(2,'0');document.getElementById('overlay').classList.remove('show');makeFloor();updateUI()}
function reveal(){for(let y=Math.max(0,player.y-7);y<=Math.min(H-1,player.y+7);y++)for(let x=Math.max(0,player.x-9);x<=Math.min(W-1,player.x+9);x++)if(Math.hypot(x-player.x,y-player.y)<8)seen[y][x]=true}
function addXP(n){player.xp+=n;while(player.xp>=player.level*20){player.xp-=player.level*20;player.level++;player.maxhp+=5;player.hp=Math.min(player.maxhp,player.hp+8);player.baseAtk++;log(`Level up! You are now level ${player.level}.`,'good')}}
function updateUI(){let s=stats();document.getElementById('hptext').textContent=`${player.hp} / ${player.maxhp}`;document.getElementById('hpbar').style.width=`${100*player.hp/player.maxhp}%`;document.getElementById('xptext').textContent=`${player.xp} / ${player.level*20}`;document.querySelector('#xpbar i').style.width=`${100*player.xp/(player.level*20)}%`;document.getElementById('levelbadge').textContent=`LVL ${player.level}`;document.getElementById('attackstat').textContent=s.atk;document.getElementById('defensestat').textContent=s.arm;document.getElementById('goldstat').textContent=player.gold;for(let t of gearTypes){let el=document.getElementById('gear'+t);el.textContent=player.gear[t]?.name||'Empty';el.classList.toggle('empty',!player.gear[t])}renderBag()}
function renderBag(){let box=document.getElementById('items');document.getElementById('packcount').textContent=`${player.bag.length} ITEMS`;if(!player.bag.length){box.innerHTML='<div style="font:10px DM Mono,monospace;color:#667080;padding:8px 2px">Your pack is empty. Search the vault.</div>';return}box.innerHTML=player.bag.map((it,i)=>`<div class="item ${selected===i?'selected':''}" data-i="${i}"><div class="icon">${it.icon}</div><div class="itemtext"><div class="itemname ${it.rarity?'rarity':''}">${it.name}${it.count>1?` ×${it.count}`:''}</div><div class="itemdesc">${it.desc}</div></div><div class="itemactions">${it.kind==='gear'?'<button class="action" data-act="equip">EQUIP</button>':it.kind==='potion'||it.kind==='scroll'?'<button class="action" data-act="use">USE</button>':''}</div></div>`).join('')}
function actItem(i,act){let it=player.bag[i];if(!it)return;if(it.kind==='gear'&&act==='equip'){let old=player.gear[it.type];player.gear[it.type]=it;player.bag.splice(i,1);if(old)player.bag.unshift({...old,kind:'gear'});log(`Equipped ${it.name}.`,'good');selected=null;updateUI();return}if(act!=='use')return;if(it.kind==='potion'){let amount=it.name==='Greater Draught'?25:14;if(player.hp===player.maxhp){log('You are already at full vitality.');return}player.hp=Math.min(player.maxhp,player.hp+amount);log(`You drink ${it.name} and recover ${amount} vitality.`,'good')}else if(it.name==='Scroll of Sparks'){let hits=enemies.filter(e=>Math.hypot(e.x-player.x,e.y-player.y)<=5);if(!hits.length){log('The sparks fizzle; no foes are close enough.');return}for(let e of hits){e.hp-=7;log(`Lightning scorches the ${e.name.toLowerCase()} for 7.`,'good');if(e.hp<=0)killEnemy(e)}enemies=enemies.filter(e=>e.hp>0)}else if(it.name==='Scroll of Warding'){player.tempArm=4;log('A ward shimmers around you. +4 armor for 8 turns.','good')}if(it.count>1)it.count--;else player.bag.splice(i,1);selected=null;advance();updateUI()}
function pickup(){let i=loot.findIndex(a=>a.x===player.x&&a.y===player.y);if(i<0)return;let it=loot.splice(i,1)[0];if(it.kind==='gold'){player.gold+=it.amount;log(`You gather ${it.amount} gold.`,'loot')}else if(it.kind==='potion'||it.kind==='scroll'){let old=player.bag.find(b=>b.name===it.name);if(old)old.count=(old.count||1)+1;else player.bag.push({...it,count:1});log(`Found ${it.name}.`,'loot')}else{player.bag.push(it);log(`Found ${it.name}. ${it.desc}.`,'loot')}}
function killEnemy(e){log(`${e.name} falls. +${e.xp} XP.`,'good');addXP(e.xp);if(rand(4)===0)loot.push({x:e.x,y:e.y,...itemLoot()})}
function attack(e){let s=stats(),d=Math.max(1,s.atk+rand(3)-1);e.hp-=d;log(`You strike the ${e.name.toLowerCase()} for ${d}.`,'good');if(e.hp<=0){killEnemy(e);enemies=enemies.filter(x=>x!==e)}else if(Math.random()<.18)log(`${e.name} staggers under the blow.`)}
function move(dx,dy){if(gameOver)return;let nx=player.x+dx,ny=player.y+dy;if(nx<0||ny<0||nx>=W||ny>=H)return;let foe=enemies.find(e=>e.x===nx&&e.y===ny);if(foe){attack(foe);advance();return}if(map[ny][nx]===1)return;if(map[ny][nx]===2){descend();return}player.x=nx;player.y=ny;pickup();advance();reveal();render();updateUI()}
function waitTurn(){if(gameOver)return;log('You hold your ground.');advance();render()}
function advance(){turn++;if(player.tempArm>0)player.tempArm--;let s=stats();for(let e of enemies){let dist=Math.abs(e.x-player.x)+Math.abs(e.y-player.y);if(dist===1){let dmg=Math.max(1,e.atk-s.arm-(player.tempArm?4:0)+rand(2));player.hp-=dmg;log(`${e.name} hits you for ${dmg}.`,player.hp<9?'warn':'');if(player.hp<=0){player.hp=0;updateUI();die();return}}else if(dist<8){let dx=Math.sign(player.x-e.x),dy=Math.sign(player.y-e.y);let opts=Math.abs(player.x-e.x)>Math.abs(player.y-e.y)?[[dx,0],[0,dy]]:[[0,dy],[dx,0]];for(let [sx,sy] of opts){let xx=e.x+sx,yy=e.y+sy;if(map[yy]?.[xx]===0&&!enemies.some(q=>q!==e&&q.x===xx&&q.y===yy)&&!(xx===player.x&&yy===player.y)){e.x=xx;e.y=yy;break}}}}if(player.gear.ring?.regen&&turn%10===0)player.hp=Math.min(player.maxhp,player.hp+player.gear.ring.regen);updateUI();render()}
function descend(){depth++;player.hp=Math.min(player.maxhp,player.hp+4);makeFloor();updateUI()}
function die(){gameOver=true;document.getElementById('endtitle').textContent='THE VAULT CLAIMS ANOTHER';document.getElementById('endcopy').textContent=`You reached depth ${depth}, level ${player.level}, and collected ${player.gold} gold. The deep keeps its secrets — for now.`;document.getElementById('overlay').classList.add('show');log('Your light fades in the dark.','warn')}
function toast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1200)}
function render(){if(!map)return;ctx.clearRect(0,0,800,608);ctx.fillStyle='#0c1017';ctx.fillRect(0,0,800,608);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let px=x*T,py=y*T,vis=Math.hypot(x-player.x,y-player.y)<8;if(!seen[y][x]){ctx.fillStyle='#0c1017';ctx.fillRect(px,py,T,T);continue}if(map[y][x]===1){ctx.fillStyle=vis?'#202632':'#171c26';ctx.fillRect(px,py,T,T);ctx.fillStyle=vis?'#2a3340':'#1c222c';ctx.fillRect(px+1,py+1,T-2,4);ctx.fillStyle='#171c25';ctx.fillRect(px+4,py+9,3,2);ctx.fillRect(px+23,py+22,4,3)}else{ctx.fillStyle=vis?'#34323a':'#24242d';ctx.fillRect(px,py,T,T);ctx.fillStyle=vis?'#3e3a40':'#2c2a32';ctx.fillRect(px+2,py+2,T-4,T-4);ctx.fillStyle='#292830';if((x*13+y*7)%7===0)ctx.fillRect(px+7,py+18,5,2);if((x*3+y*11)%9===0)ctx.fillRect(px+22,py+8,3,3);if(map[y][x]===2){ctx.fillStyle='#181a21';ctx.beginPath();ctx.ellipse(px+16,py+17,10,12,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d5a862';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#f0ce84';ctx.fillRect(px+14,py+3,4,8);ctx.fillRect(px+11,py+14,10,3);}}
 if(!vis){ctx.fillStyle='#070a10aa';ctx.fillRect(px,py,T,T)}else{ctx.strokeStyle='#ffffff08';ctx.strokeRect(px,py,T,T)}}
 for(let it of loot){if(!seen[it.y]?.[it.x]||Math.hypot(it.x-player.x,it.y-player.y)>=8)continue;let x=it.x*T,y=it.y*T;ctx.fillStyle=it.kind==='gold'?'#f0c66f':it.kind==='gear'?'#adc5f4':'#81d6c3';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.font='bold 17px sans-serif';ctx.textAlign='center';ctx.fillText(it.icon,x+16,y+22);ctx.shadowBlur=0}
 for(let e of enemies){if(!seen[e.y]?.[e.x]||Math.hypot(e.x-player.x,e.y-player.y)>=8)continue;let x=e.x*T,y=e.y*T;ctx.fillStyle='#0a0c11aa';ctx.beginPath();ctx.ellipse(x+16,y+26,10,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.color;ctx.font='bold 22px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(e.icon,x+16,y+22);if(e.hp<e.maxhp){ctx.fillStyle='#161820';ctx.fillRect(x+5,y+2,22,3);ctx.fillStyle='#ec7775';ctx.fillRect(x+5,y+2,22*e.hp/e.maxhp,3)}}
 let x=player.x*T,y=player.y*T;ctx.fillStyle='#06080c99';ctx.beginPath();ctx.ellipse(x+16,y+27,11,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e2bc78';ctx.fillRect(x+12,y+5,8,7);ctx.fillStyle='#c9d6d2';ctx.fillRect(x+10,y+12,12,11);ctx.fillStyle='#8299a8';ctx.fillRect(x+11,y+22,4,6);ctx.fillRect(x+18,y+22,4,6);ctx.fillStyle='#6e4a3b';ctx.fillRect(x+11,y+7,10,3);ctx.fillStyle='#f0d7a1';ctx.fillRect(x+14,y+8,2,2);
}
function act(dx,dy){move(dx,dy)}
document.addEventListener('keydown',e=>{let k=e.key.toLowerCase(),dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[k]){e.preventDefault();act(...dirs[k])}else if(k===' '||k==='.') {e.preventDefault();waitTurn()}else if(k==='e'){let i=loot.findIndex(a=>a.x===player.x&&a.y===player.y);if(i>=0){let it=loot.splice(i,1)[0];if(it.kind==='gold')player.gold+=it.amount;else player.bag.push(it);log(`Picked up ${it.name==='Gold'?it.amount+' gold':it.name}.`,'loot');updateUI();render()}}});
document.querySelector('.mobilepad').addEventListener('click',e=>{let dir=e.target.dataset.dir;let d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];if(d)move(...d);else if(dir==='wait')waitTurn()});
canvas.addEventListener('click',e=>{let r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)/r.width*W),y=Math.floor((e.clientY-r.top)/r.height*H),dx=x-player.x,dy=y-player.y;if(Math.abs(dx)<=1&&Math.abs(dy)<=1&&(dx||dy))move(dx,dy)});
document.getElementById('items').addEventListener('click',e=>{let row=e.target.closest('.item');if(!row)return;let i=Number(row.dataset.i),act=e.target.dataset.act;if(act)actItem(i,act);else{selected=selected===i?null:i;renderBag()}});
document.getElementById('restart').addEventListener('click',()=>start());
run=0;start();
</script>
</body></html>
